import re
from openpyxl import load_workbook
from openpyxl.cell.cell import MergedCell

INPUT_FILE = "ssb_290_27_init.xlsx"
OUTPUT_FILE = "output.xlsx"
SHEET_NAME = "Sheet1"

# Pattern for the alphanumeric strings to alter:
#   - starts with a 2 or 3 letter uppercase code
#   - optionally a space between the code and the number
#     (the task mentions the space occurs when the code is 2 letters long)
#   - followed by a number
# Anything else in column B (dates, plain numbers, other text) stays untouched.
CODE_PATTERN = re.compile(r'^\s*([A-Z]{2,3})\s*(\d+(?:\.\d+)?)\s*$')


def strip_letter_code(value):
    """Return the value with its leading uppercase letter code (and any
    separating space) removed, leaving just the number. Values that are not
    strings matching the described pattern are returned unchanged."""
    if not isinstance(value, str):
        return value  # dates / numbers / None are left as-is
    match = CODE_PATTERN.match(value)
    if match is None:
        return value  # does not match the code+number pattern -> unchanged
    number_text = match.group(2)
    if '.' in number_text:
        return float(number_text)
    return int(number_text)


def main():
    wb = load_workbook(INPUT_FILE)  # loads all existing sheets/formats

    if SHEET_NAME in wb.sheetnames:
        ws = wb[SHEET_NAME]
    else:
        ws = wb.active

    # Work on column B only; all other columns and sheets remain untouched.
    for row in ws.iter_rows(min_col=2, max_col=2):
        for cell in row:
            if isinstance(cell, MergedCell):
                continue
            current = cell.value
            if isinstance(current, str):
                new_value = strip_letter_code(current)
                if new_value != current:
                    cell.value = new_value  # e.g. 'PID1' -> 1, 'GG 1' -> 1

    wb.save(OUTPUT_FILE)


if __name__ == "__main__":
    main()
